// ---- EDIT THESE THREE NAMES TO MATCH YOUR NODE TITLES ----
const TRIGGER_NODE = 'When Executed by Another Workflow';
const ORDER_NODE   = 'Execute a SQL query';
const ALT_NODE     = 'Get Alternatives';
// -----------------------------------------------------------

const input = $(TRIGGER_NODE).first().json;
const o = $(ORDER_NODE).first().json;
const opts = $(ALT_NODE).all()
  .map(i => i.json)
  .filter(x => x && x.sku);

const wantSize  = String(input.desired_size  ?? '').trim().toLowerCase();
const wantColor = String(input.desired_color ?? '').trim().toLowerCase();
const cur = String(o.currency ?? '');
const money = n => (cur === 'INR' ? 'Rs ' : 'AED ') + Math.round(Number(n));

const out = (ok, reason, list = [], left = 0) => [{
  json: {
    eligible: ok ? 'true' : 'false',
    reason,
    item: String(o.item ?? ''),
    size: String(o.size ?? ''),
    sku: String(o.sku ?? ''),
    paid: String(o.amount ?? ''),
    currency: cur,
    days_left: String(left),
    option_count: String(list.length),
    options: list.join('\n'),
  },
}];

if (o.refunded === 'yes' || Number(o.refund_count) > 0) {
  return out(false, 'This order was already refunded');
}
if (Number(o.return_count) > 0) {
  return out(false, 'A return is already in progress for this order');
}
if (Number(o.exchange_count) > 0) {
  return out(false, 'An exchange is already in progress for this order');
}
if (o.order_status !== 'delivered') {
  return out(false, 'The order has not been delivered yet, so it cannot be exchanged. Offer tracking, or a cancellation if it has not shipped');
}

const days = Number(o.days_since_delivery) || 0;
const left = (Number(o.return_window_days) || 0) - days;
if (left < 0) {
  return out(false, `Delivered ${days} days ago; the exchange window is ${o.return_window_days} days`, [], left);
}

const paid = Number(o.amount);
let list = opts.filter(x => !(x.sku === o.sku && x.size === o.size));
let note = '';

if (wantSize || wantColor) {
  const pick = list.filter(x =>
    (!wantSize  || String(x.size  ?? '').toLowerCase().includes(wantSize)) &&
    (!wantColor || String(x.color ?? '').toLowerCase().includes(wantColor))
  );
  if (pick.length === 0) {
    if (list.length > 0) note = 'Nothing in stock matches that exactly; these are the other choices. ';
  } else {
    list = pick;
  }
}

const lines = list.slice(0, 5).map((x, i) => {
  const credit = paid - Number(x.price);
  const tail = credit > 0.5 ? `${money(credit)} would be credited back` : 'same price';
  return `${i + 1}) ${x.name} (sku ${x.sku}), size ${x.size}, ${money(x.price)}, ${x.stock_quantity} in stock, ${tail}`;
});

if (lines.length === 0) {
  return out(false, 'Nothing else is in stock at the same price or lower', [], left);
}
return out(true, note + 'Eligible', lines, left);
